 abelDivAffTrans : divFunctorAff C n ⟶ picDegLayerFunctor C (n : ℤ) where\\nAlgebraicJacobian/Picard/Pic0EndgameContract.lean:61:      Over.sigmaExtension (Spec (.of k)) (picDegLayerFunctor C (n : ℤ)) :=\\nAlgebraicJacobian/Picard/Pic0EndgameContract.lean:86:      Over.sigmaExtension (Spec (.of k)) (picDegLayerFunctor C (genus C : ℤ)) :=\\nAlgebraicJacobian/Picard/Pic0RankOnePresentation.lean:19:An element of `picDegLayerFunctor` is an etale-plus class, not a chosen line bundle.  The\\n\", \"exit_code\": 0}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:03.973462+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc 'git log --oneline --decorate -12 -- AlgebraicJacobian/Picard/Pic0RankOneLocus.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneChart.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneFibre.lean'\"}, \"usage\": null}\n{\"kind\": \"tool_result\", \"at\": \"2026-08-06T03:54:03.973476+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"fatal: your current branch 'main' does not have any commits yet\\n\", \"exit_code\": 128}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:21.748212+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc '\\\"$HORIZON_GIT\\\" show 298549f011 --stat --oneline && \\\"$HORIZON_GIT\\\" show 298549f011:MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0RankOneLocus.lean | sed -n '\\\"'1,140p'\\\"\"}, \"usage\": null}\n{\"kind\": \"tool_result\", \"at\": \"2026-08-06T03:54:21.748224+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"298549f011 ajcr: define pullback-stable rank-one locus\\n .../AlgebraicJacobian/Picard/Pic0CriticalPath.lean | 11 ++-\\n .../AlgebraicJacobian/Picard/Pic0RankOneLocus.lean | 95 ++++++++++++++++++++++\\n 2 files changed, 103 insertions(+), 3 deletions(-)\\n/-\\nCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\nReleased under Apache 2.0 license as described in the file LICENSE.\\nAuthors: The AlgebraicJacobian Contributors\\n-/\\nimport AlgebraicJacobian.Picard.Pic0RankOnePresentation\\nimport Mathlib.CategoryTheory.Subfunctor.Image\\n\\n/-!\\n# The presentation locus for the rank-one Abel map\\n\\n`PicRankOneOpen` is the functorial locus in the degree-`genus C` Picard layer whose pullback to\\nevery affine test admits a tied `PicRankOneLocalPresentation`.  Quantifying after every affine\\npullback makes the condition intrinsic on arbitrary test schemes; stability under further\\npullback is exactly `picEtMap_comp`.\\n\\nThe remaining declarations form the corresponding preimages in the widened divisor functor and\\nin its canonical representing Yoneda functor, together with the restricted Abel transformations.\\nThese are logical subfunctors only.  In particular, this file does not prove that\\n`PicRankOneOpen` is represented by an open subscheme, and it reserves `DivRankOneOpen` for the\\nfuture actual open subscheme of the divisor representer.\\n-/\\n\\nset_option autoImplicit false\\nset_option maxSynthPendingDepth 3\\n\\nuniverse u\\n\\nopen CategoryTheory Limits Opposite MonoidalCategory CartesianMonoidalCategory\\n\\nnamespace AlgebraicGeometry\\n\\nvariable {k : Type u} [Field k] {C : Over (Spec (.of k))}\\nvariable [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n  [GeometricallyIrreducible C.hom]\\nvariable (pi : C.left ⟶ P1 k) [IsFinite pi]\\n\\nnoncomputable section\\n\\n/-- The rank-one presentation locus in the degree-`genus C` Picard layer.\\n\\nMembership means that every affine pullback of the input plus class admits a local presentation\\ntied to that pullback.  This is the correct logical subfunctor underlying the future open Picard\\nlocus; no openness or representability assertion is part of this definition. -/\\ndef PicRankOneOpen :\\n    Subfunctor (picDegLayerFunctor C (genus C : ℤ)) where\\n  obj T := {lam | ∀ (A : Type u) [CommRing A] [Algebra k A]\\n      (t : overSpec k A ⟶ T.unop),\\n    Nonempty (PicRankOneLocalPresentation pi\\n      ((picDegLayerFunctor C (genus C : ℤ)).map t.op lam))}\\n  map {T T'} f lam hlam A _ _ t := by\\n    let F := picDegLayerFunctor C (genus C : ℤ)\\n    have e : F.map t.op (F.map f lam) = F.map (t ≫ f.unop).op lam := by\\n      apply Subtype.ext\\n      exact (picEtMap_comp C f.unop t lam.1).symm\\n    rw [e]\\n    exact hlam A (t ≫ f.unop)\\n\\n/-- The inverse image of `PicRankOneOpen` under the affine widened Abel transformation.\\n\\nThis name deliberately records only a presentation-theoretic preimage.  It is not the future\\nopen subscheme `DivRankOneOpen`. -/\\ndef divRankOnePresentationPreimageAff :\\n    Subfunctor (divFunctorAff C (genus C)) :=\\n  (PicRankOneOpen pi).preimage (abelDivAffTrans C (genus C))\\n\\n/-- The same presentation preimage on the Yoneda functor of the canonical genus divisor\\nrepresenter. -/\\ndef divRankOnePresentationPreimageRepresenter :\\n    Subfunctor (yoneda.obj (divRepAffGenusScheme C)) :=\\n  (divRankOnePresentationPreimageAff pi).preimage\\n    (divFunctorAff_genus_representableBy C).toIso.hom\\n\\n/-- The affine Abel transformation restricted to the rank-one presentation preimage. -/\\ndef rankOneAbelAff :\\n    (divRankOnePresentationPreimageAff pi).toFunctor ⟶\\n      (PicRankOneOpen pi).toFunctor :=\\n  (PicRankOneOpen pi).fromPreimage (abelDivAffTrans C (genus C))\\n\\n/-- Restrict the canonical representation isomorphism to the rank-one presentation preimage. -/\\ndef rankOneRepresenterRestriction :\\n    (divRankOnePresentationPreimageRepresenter pi).toFunctor ⟶\\n      (divRankOnePresentationPreimageAff pi).toFunctor :=\\n  (divRankOnePresentationPreimageAff pi).fromPreimage\\n    (divFunctorAff_genus_representableBy C).toIso.hom\\n\\n/-- The represented genus Abel map restricted to the rank-one presentation preimage. -/\\ndef rankOneAbelRepresented :\\n    (divRankOnePresentationPreimageRepresenter pi).toFunctor ⟶\\n      (PicRankOneOpen pi).toFunctor :=\\n  rankOneRepresenterRestriction pi ≫ rankOneAbelAff pi\\n\\nend\\n\\nend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:22.614931+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc \\\"printf '%s\\\\\\\\n' \\\\\\\"\\\"'$HORIZON_GIT\\\"; \\\"$HORIZON_GIT\\\" status --short -- AlgebraicJacobian/Picard/Pic0RankOneLocus.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneChart.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneFibre.lean'\"}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:24.470000+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc '\\\"$HORIZON_GIT\\\" log --oneline --decorate -15 -- AlgebraicJacobian/Picard/Pic0RankOneLocus.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneChart.lean AlgebraicJacobian/Picard/DivSchemeRedesignRankOneFibre.lean'\"}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:46.800895+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc \\\"nl -ba AlgebraicJacobian/Picard/Pic0RankOneLocalDivisor.lean | sed -n '1,360p'\\\"\"}, \"usage\": null}\n{\"kind\": \"tool_result\", \"at\": \"2026-08-06T03:54:46.800908+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"     1\\t/-\\n     2\\tCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\n     3\\tReleased under Apache 2.0 license as described in the file LICENSE.\\n     4\\tAuthors: The AlgebraicJacobian Contributors\\n     5\\t-/\\n     6\\timport AlgebraicJacobian.Picard.Pic0RankOnePresentation\\n     7\\timport AlgebraicJacobian.Picard.Pic0AdmissibleAbelEtaleSurjectiveEffectivity\\n     8\\timport AlgebraicJacobian.Picard.DivisorFamilyMonoH1\\n     9\\timport Mathlib.RingTheory.TensorProduct.Finite\\n    10\\t\\n    11\\t/-!\\n    12\\t# The consumed local divisor package for the rank-one route\\n    13\\t\\n    14\\tThis module is the first divisor consumer of PicRankOneLocalPresentation.  The projective\\n    15\\trank-one H0 module supplies a basic open and a section which is nonzero on every residue fibre\\n    16\\tthere.  The datum-side section construction then gives regular local equations, and the widened\\n    17\\teffectivity engine packages those equations as a DivFamZarAff of degree genus C.\\n    18\\t\\n    19\\tThe package is deliberately local and presentation-tied.  It does not define the canonical\\n    20\\tfamily-level divisorOfRankOne, identify the equations with the native zero locus, or assert\\n    21\\tthat the rank-one locus is represented by an open subscheme.  Those remain the next contracts.\\n    22\\t-/\\n    23\\t\\n    24\\tset_option autoImplicit false\\n    25\\t\\n    26\\tuniverse u\\n    27\\t\\n    28\\topen CategoryTheory Limits TopologicalSpace Opposite MonoidalCategory\\n    29\\t  CartesianMonoidalCategory\\n    30\\topen scoped TensorProduct\\n    31\\t\\n    32\\tnamespace AlgebraicGeometry\\n    33\\t\\n    34\\tattribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra\\n    35\\tattribute [local instance 10000] relCurve.instOver\\n    36\\t\\n    37\\tvariable {k : Type u} [Field k] {C : Over (Spec (.of k))}\\n    38\\tvariable [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n    39\\t  [GeometricallyIrreducible C.hom]\\n    40\\tvariable {A : Type u} [CommRing A] [Algebra k A]\\n    41\\tvariable {pi : C.left ⟶ P1 k} [IsFinite pi]\\n    42\\tvariable {lam : picDegLayer C (genus C : ℤ) (overSpec k A)}\\n    43\\t\\n    44\\tnamespace PicRankOneLocalPresentation\\n    45\\t\\n    46\\t/- The degree theorem needs the base-change geometric package under the local relCurve instance,\\n    47\\t   which has lower priority in the general curve API. -/\\n    48\\tnoncomputable local instance (priority := 20000) rankOneLocalDivisorOver\\n    49\\t    (L : Type u) [Field L] [Algebra k L] :\\n    50\\t    (relCurve C L).Over (Spec (.of L)) :=\\n    51\\t  instOverBaseChange C L\\n    52\\t\\n    53\\tnoncomputable local instance rankOneLocalDivisorSmooth\\n    54\\t    (L : Type u) [Field L] [Algebra k L] :\\n    55\\t    SmoothOfRelativeDimension 1 (relCurve C L ↘ Spec (.of L)) :=\\n    56\\t  instSmoothOfRelativeDimensionBaseChange C L\\n    57\\t\\n    58\\tnoncomputable local instance rankOneLocalDivisorIntegral\\n    59\\t    (L : Type u) [Field L] [Algebra k L] :\\n    60\\t    IsIntegral (relCurve C L) :=\\n    61\\t  instIsIntegralBaseChange C L\\n    62\\t\\n    63\\tnoncomputable local instance rankOneLocalDivisorQuasiCompact\\n    64\\t    (L : Type u) [Field L] [Algebra k L] :\\n    65\\t    QuasiCompact (relCurve C L ↘ Spec (.of L)) :=\\n    66\\t  instQuasiCompactBaseChange C L\\n    67\\t\\n    68\\tnoncomputable local instance rankOneLocalDivisorFiniteH0\\n    69\\t    (L : Type u) [Field L] [Algebra k L] :\\n    70\\t    Module.Finite L (Sheaf.HModule ((relCurve C L).moduleKSheaf L) 0) :=\\n    71\\t  instModuleFiniteHModuleZeroBaseChange C L\\n    72\\t\\n    73\\tnoncomputable local instance rankOneLocalDivisorFiniteH1\\n    74\\t    (L : Type u) [Field L] [Algebra k L] :\\n    75\\t    Module.Finite L (Sheaf.HModule ((relCurve C L).moduleKSheaf L) 1) :=\\n    76\\t  instModuleFiniteHModuleOneBaseChange C L\\n    77\\t\\n    78\\t/-! ## Regularity and degree of the local equations -/\\n    79\\t\\n    80\\t/-- The local equations cut from the tied datum section remain regular after every field-valued\\n    81\\tcoefficient extension.  This is the regularity input consumed by the widened effectivity\\n    82\\tengine, derived from the same fibrewise nonvanishing hypothesis used in the construction. -/\\n    83\\ttheorem baseOpenDatumSectionLocalEquations_fibrewiseRegular\\n    84\\t    (P : PicRankOneLocalPresentation pi lam)\\n    85\\t    [IsNoetherianRing P.cover.Carrier]\\n    86\\t    (f : P.cover.Carrier)\\n    87\\t    (y : Sheaf.HModule P.datum.sheaf 0)\\n    88\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n    89\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n    90\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n    91\\t          p.asIdeal.ResidueField) ≠ 0)\\n    92\\t    (L : Type u) [Field L] [Algebra k L]\\n    93\\t    [Algebra (Localization.Away f) L]\\n    94\\t    [IsScalarTower k (Localization.Away f) L]\\n    95\\t    (z : relCurve C L) :\\n    96\\t    ((relCurve C L).presheaf.germ\\n    97\\t      (((P.baseOpenDatumSectionLocalEquations f y hy).cover.pullback\\n    98\\t        (relCurveMap C (Localization.Away f) L)).opens z) z\\n    99\\t      (((P.baseOpenDatumSectionLocalEquations f y hy).cover.pullback\\n   100\\t        (relCurveMap C (Localization.Away f) L)).mem_opens z)).hom\\n   101\\t      (Scheme.LocalEquations.pullbackEqn\\n   102\\t        (relCurveMap C (Localization.Away f) L)\\n   103\\t        (P.baseOpenDatumSectionLocalEquations f y hy) z) ∈\\n   104\\t      nonZeroDivisors ((relCurve C L).presheaf.stalk z) := by\\n   105\\t  let B := Localization.Away f\\n   106\\t  let D := P.datum.baseChange B\\n   107\\t  let s : ↥(gluedSubmodule B D.pieces D.unit ⊤) :=\\n   108\\t    P.datumSectionBaseChange B y\\n   109\\t  have hsec : ∀ q : PrimeSpectrum B,\\n   110\\t      D.sectionsMapTop q.asIdeal.ResidueField\\n   111\\t        (P.datumSectionBaseChange B y) ≠ 0 :=\\n   112\\t    fun q => P.sectionsMapTop_datumSectionBaseChange_away_ne_zero f y hy q\\n   113\\t  have hfib : ∀ (j : D.index) (q : PrimeSpectrum B), Function.Injective\\n   114\\t      ((Scheme.mulSectionEnd B (D.component s j)).rTensor q.asIdeal.ResidueField) :=\\n   115\\t    fun j q => D.injective_rTensor_component_of_sectionsMapTop_ne_zero\\n   116\\t      s q (hsec q) j\\n   117\\t  unfold baseOpenDatumSectionLocalEquations sectionLocalEquationsOfDatumSectionBaseChange\\n   118\\t  exact D.germ_self_pullbackEqn_sectionLocalEquationsOfFibrewiseRegular\\n   119\\t    s hfib L z\\n   120\\t\\n   121\\t/-- The local equations have the genus class degree after every field-valued extension.  The\\n   122\\tcalculation uses the datum class law and datum_classDeg_baseChange, so the degree is tied to\\n   123\\tthe presentation rather than supplied as an unrelated witness. -/\\n   124\\ttheorem baseOpenDatumSectionLocalEquations_classDeg\\n   125\\t    (P : PicRankOneLocalPresentation pi lam)\\n   126\\t    [IsNoetherianRing P.cover.Carrier]\\n   127\\t    (f : P.cover.Carrier)\\n   128\\t    (y : Sheaf.HModule P.datum.sheaf 0)\\n   129\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   130\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   131\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   132\\t          p.asIdeal.ResidueField) ≠ 0)\\n   133\\t    (L : Type u) [Field L] [Algebra k L]\\n   134\\t    [Algebra (Localization.Away f) L]\\n   135\\t    [IsScalarTower k (Localization.Away f) L] :\\n   136\\t    classDeg L\\n   137\\t      (Scheme.CechPic.map (relCurveMap C (Localization.Away f) L)\\n   138\\t        (P.baseOpenDatumSectionLocalEquations f y hy).picClass) = genus C := by\\n   139\\t  letI : Algebra P.cover.Carrier L :=\\n   140\\t    ((algebraMap (Localization.Away f) L).comp\\n   141\\t      (algebraMap P.cover.Carrier (Localization.Away f))).toAlgebra\\n   142\\t  haveI : IsScalarTower P.cover.Carrier (Localization.Away f) L :=\\n   143\\t    IsScalarTower.of_algebraMap_eq' rfl\\n   144\\t  haveI : IsScalarTower k P.cover.Carrier L :=\\n   145\\t    IsScalarTower.of_algebraMap_eq' (by\\n   146\\t      rw [RingHom.algebraMap_toAlgebra, RingHom.comp_assoc,\\n   147\\t        ← IsScalarTower.algebraMap_eq k P.cover.Carrier (Localization.Away f),\\n   148\\t        ← IsScalarTower.algebraMap_eq k (Localization.Away f) L])\\n   149\\t  rw [P.baseOpenDatumSectionLocalEquations_picClass f y hy,\\n   150\\t    P.datum.cechPicClass_baseChange (Localization.Away f),\\n   151\\t    ← MonoidHom.comp_apply, ← Scheme.CechPic.map_comp,\\n   152\\t    relCurveMap_comp]\\n   153\\t  exact P.datum_classDeg_baseChange L\\n   154\\t\\n   155\\t/-! ## The local widened divisor and its immediate consumer -/\\n   156\\t\\n   157\\t/- The next canonicality edge is expressed first in the localized H⁰ module.  The datum\\n   158\\t   section/native comparison needed to transport this unit to local equations is deliberately\\n   159\\t   a separate contract. -/\\n   160\\ttheorem existsUnique_unit_tensorAway_rankOne_generators\\n   161\\t    (P : PicRankOneLocalPresentation pi lam)\\n   162\\t    (f : P.cover.Carrier)\\n   163\\t    (y y' : Sheaf.HModule P.datum.sheaf 0)\\n   164\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   165\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   166\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   167\\t          p.asIdeal.ResidueField) ≠ 0)\\n   168\\t    (hy' : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   169\\t      (y' ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   170\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   171\\t          p.asIdeal.ResidueField) ≠ 0) :\\n   172\\t    ∃! v : (Localization.Away f)ˣ,\\n   173\\t      ((1 : Localization.Away f) ⊗ₜ[P.cover.Carrier] y') =\\n   174\\t        (v : Localization.Away f) •\\n   175\\t          ((1 : Localization.Away f) ⊗ₜ[P.cover.Carrier] y) := by\\n   176\\t  let B := Localization.Away f\\n   177\\t  let Q := Sheaf.HModule P.datum.sheaf 0\\n   178\\t  letI : Module.Finite P.cover.Carrier Q := P.h0_finite\\n   179\\t  letI : Module.Projective P.cover.Carrier Q := P.h0_projective\\n   180\\t  have hrankB : ∀ q : PrimeSpectrum B,\\n   181\\t      Module.rankAtStalk (B ⊗[P.cover.Carrier] Q) q = 1 := by\\n   182\\t    intro q\\n   183\\t    rw [Module.rankAtStalk_baseChange]\\n   184\\t    exact P.h0_rank_one (PrimeSpectrum.comap\\n   185\\t      (algebraMap P.cover.Carrier B) q)\\n   186\\t  exact Module.existsUnique_unit_smul_of_forall_tmul_ne_zero\\n   187\\t    hrankB ((1 : B) ⊗ₜ[P.cover.Carrier] y) ((1 : B) ⊗ₜ[P.cover.Carrier] y')\\n   188\\t    (AlgebraicGeometry.PicRankOneLocalPresentation.tensorAwayGenerator_fibre_ne_zero\\n   189\\t      f y hy)\\n   190\\t    (AlgebraicGeometry.PicRankOneLocalPresentation.tensorAwayGenerator_fibre_ne_zero\\n   191\\t      f y' hy')\\n   192\\t\\n   193\\t/-- The widened divisor cut by a tied rank-one section on its basic open. -/\\n   194\\tnoncomputable def baseOpenRankOneDivisor\\n   195\\t    (P : PicRankOneLocalPresentation pi lam)\\n   196\\t    [IsNoetherianRing P.cover.Carrier]\\n   197\\t    (f : P.cover.Carrier)\\n   198\\t    (y : Sheaf.HModule P.datum.sheaf 0)\\n   199\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   200\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   201\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   202\\t          p.asIdeal.ResidueField) ≠ 0) :\\n   203\\t    DivFamZarAff C (Localization.Away f) (genus C) :=\\n   204\\t  divFamZarAffOfFibrewiseRegularLocalEquations C (genus C)\\n   205\\t    (P.baseOpenDatumSectionLocalEquations f y hy) pi\\n   206\\t    (P.baseOpenDatumSectionLocalEquations_fibrewiseRegular f y hy)\\n   207\\t    (P.baseOpenDatumSectionLocalEquations_classDeg f y hy)\\n   208\\t\\n   209\\t@[simp]\\n   210\\ttheorem baseOpenRankOneDivisor_picClass\\n   211\\t    (P : PicRankOneLocalPresentation pi lam)\\n   212\\t    [IsNoetherianRing P.cover.Carrier]\\n   213\\t    (f : P.cover.Carrier)\\n   214\\t    (y : Sheaf.HModule P.datum.sheaf 0)\\n   215\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   216\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   217\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   218\\t          p.asIdeal.ResidueField) ≠ 0) :\\n   219\\t    (P.baseOpenRankOneDivisor f y hy).picClass =\\n   220\\t      (P.datum.baseChange (Localization.Away f)).cechPicClass := by\\n   221\\t  unfold baseOpenRankOneDivisor\\n   222\\t  rw [picClass_divFamZarAffOfFibrewiseRegularLocalEquations]\\n   223\\t  exact P.baseOpenDatumSectionLocalEquations_picClass f y hy\\n   224\\t\\n   225\\t/-- The Abel value of the local divisor is the restriction of the input Picard datum.  This is\\n   226\\tthe immediate consumer which keeps the widened divisor tied to the chosen presentation. -/\\n   227\\ttheorem baseOpenRankOneDivisor_abelAff\\n   228\\t    (P : PicRankOneLocalPresentation pi lam)\\n   229\\t    [IsNoetherianRing P.cover.Carrier]\\n   230\\t    (f : P.cover.Carrier)\\n   231\\t    (y : Sheaf.HModule P.datum.sheaf 0)\\n   232\\t    (hy : ∀ p : PrimeSpectrum P.cover.Carrier, f ∉ p.asIdeal →\\n   233\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   234\\t        Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   235\\t          p.asIdeal.ResidueField) ≠ 0) :\\n   236\\t    abelDivAffPlus C (Localization.Away f) (P.baseOpenRankOneDivisor f y hy) =\\n   237\\t      PicEtAff.mapAlg C ((Algebra.ofId P.cover.Carrier (Localization.Away f)).restrictScalars k)\\n   238\\t        (PicEtAff.mapAlg C ((Algebra.ofId A P.cover.Carrier).restrictScalars k)\\n   239\\t          (picEtAffineEquiv C A lam.1)) := by\\n   240\\t  let B := Localization.Away f\\n   241\\t  let iota : A →ₐ[k] P.cover.Carrier :=\\n   242\\t    (Algebra.ofId A P.cover.Carrier).restrictScalars k\\n   243\\t  let psi : P.cover.Carrier →ₐ[k] B :=\\n   244\\t    (Algebra.ofId P.cover.Carrier B).restrictScalars k\\n   245\\t  let F := P.baseOpenRankOneDivisor f y hy\\n   246\\t  have hFclass : F.picClass = (P.datum.baseChange B).cechPicClass :=\\n   247\\t    P.baseOpenRankOneDivisor_picClass f y hy\\n   248\\t  have hrel : (relPicMk C (overSpec k B)) F.picClass =\\n   249\\t      relPicAlgMap C psi (P.representative : relPic C (overSpec k P.cover.Carrier)) := by\\n   250\\t    rw [hFclass, P.datum_class, relPicAlgMap_mk]\\n   251\\t    have hcurve : Over.Hom.left (C ◁ Over.overSpecMap psi) =\\n   252\\t        relCurveMap C P.cover.Carrier B := by\\n   253\\t      refine congrArg (fun f : overSpec k B ⟶ overSpec k P.cover.Carrier => (C ◁ f).left) ?_\\n   254\\t      exact Over.OverMorphism.ext rfl\\n   255\\t    rw [P.datum.cechPicClass_baseChange B, hcurve]\\n   256\\t    rfl\\n   257\\t  calc\\n   258\\t    abelDivAffPlus C B F = PicEtAff.unit C B ((relPicMk C (overSpec k B)) F.picClass) := rfl\\n   259\\t    _ = PicEtAff.unit C B (relPicAlgMap C psi\\n   260\\t      (P.representative : relPic C (overSpec k P.cover.Carrier))) := by rw [hrel]\\n   261\\t    _ = PicEtAff.mapAlg C psi\\n   262\\t      (PicEtAff.unit C P.cover.Carrier\\n   263\\t        (P.representative : relPic C (overSpec k P.cover.Carrier))) := by\\n   264\\t      rw [PicEtAff.mapAlg_unit]\\n   265\\t    _ = PicEtAff.mapAlg C psi (PicEtAff.mapAlg C iota (picEtAffineEquiv C A lam.1)) := by\\n   266\\t      congr 1\\n   267\\t      rw [← P.represents, PicEtAff.mapAlg_mk_eq_unit_self]\\n   268\\t\\n   269\\t/-- Every base point of a rank-one presentation has a tied local widened divisor.  The final\\n   270\\tconjunct retains the native counit identity for the very same section. -/\\n   271\\ttheorem exists_baseOpen_rankOne_divisor_with_evaluation\\n   272\\t    (P : PicRankOneLocalPresentation pi lam)\\n   273\\t    [IsNoetherianRing P.cover.Carrier]\\n   274\\t    (p : PrimeSpectrum P.cover.Carrier) :\\n   275\\t    ∃ f : P.cover.Carrier, f ∉ p.asIdeal ∧\\n   276\\t      ∃ (y : Sheaf.HModule P.datum.sheaf 0)\\n   277\\t        (hy : ∀ q : PrimeSpectrum P.cover.Carrier, f ∉ q.asIdeal →\\n   278\\t          (y ⊗ₜ (1 : q.asIdeal.ResidueField) :\\n   279\\t            Sheaf.HModule P.datum.sheaf 0 ⊗[P.cover.Carrier]\\n   280\\t              q.asIdeal.ResidueField) ≠ 0),\\n   281\\t        (P.baseOpenRankOneDivisor f y hy).picClass =\\n   282\\t            (P.datum.baseChange (Localization.Away f)).cechPicClass ∧\\n   283\\t          (Scheme.Modules.Hom.app P.evaluation\\n   284\\t            ((relCurve C P.cove