e P.datum.sheaf 0) :\\n   365\\t    (Scheme.Modules.Hom.app P.evaluation\\n   366\\t      ((relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier)) ⁻¹ᵁ\\n   367\\t        (⊤ : (Spec (.of P.cover.Carrier)).Opens))).hom\\n   368\\t      (P.evaluationLiftOfH0 y) = P.pushforwardSectionOfH0 y := by\\n   369\\t  have h := congrArg\\n   370\\t    (fun (f : (Scheme.Modules.pushforward\\n   371\\t        (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module ⟶\\n   372\\t      (Scheme.Modules.pushforward\\n   373\\t        (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module) =>\\n   374\\t      (Scheme.Modules.Hom.app f (⊤ : (Spec (.of P.cover.Carrier)).Opens)).hom\\n   375\\t        (P.pushforwardSectionOfH0 y))\\n   376\\t    ((Scheme.Modules.pullbackPushforwardAdjunction\\n   377\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).right_triangle_components\\n   378\\t        P.module)\\n   379\\t  exact h\\n   380\\t\\n   381\\t/-! ## Local-away generators for the canonical evaluation -/\\n   382\\t\\n   383\\t/-- Nonvanishing on every residue-field fibre of `D(f)` survives passage from the\\n   384\\tcorresponding prime of the original ring to the residue field of a prime of `A_f`.\\n   385\\t\\n   386\\tThe residue-field comparison is an isomorphism because localization induces bijective\\n   387\\tresidue-field maps.  Keeping this as a private module lemma prevents the rank-one\\n   388\\tconstruction from depending on a false definitional transitivity of datum base change. -/\\n   389\\tprivate theorem fibre_tmul_ne_zero_of_away\\n   390\\t    {A Q : Type u} [CommRing A] [AddCommGroup Q] [Module A Q]\\n   391\\t    (f : A) (y : Q)\\n   392\\t    (hy : ∀ p : PrimeSpectrum A, f ∉ p.asIdeal →\\n   393\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   394\\t        Q ⊗[A] p.asIdeal.ResidueField) ≠ 0)\\n   395\\t    (q : PrimeSpectrum (Localization.Away f)) :\\n   396\\t    ((1 : q.asIdeal.ResidueField) ⊗ₜ[A] y :\\n   397\\t      q.asIdeal.ResidueField ⊗[A] Q) ≠ 0 := by\\n   398\\t  let p : PrimeSpectrum A :=\\n   399\\t    PrimeSpectrum.comap (algebraMap A (Localization.Away f)) q\\n   400\\t  have hfp : f ∉ p.asIdeal := by\\n   401\\t    intro hf\\n   402\\t    refine q.isPrime.ne_top (Ideal.eq_top_of_isUnit_mem q.asIdeal\\n   403\\t      (Ideal.mem_comap.mp hf) ?_)\\n   404\\t    exact IsLocalization.Away.algebraMap_isUnit f\\n   405\\t  have hp : ((1 : p.asIdeal.ResidueField) ⊗ₜ[A] y :\\n   406\\t      p.asIdeal.ResidueField ⊗[A] Q) ≠ 0 := by\\n   407\\t    have h := (TensorProduct.comm A Q p.asIdeal.ResidueField).map_ne_zero_iff.mpr\\n   408\\t      (hy p hfp)\\n   409\\t    simpa only [TensorProduct.comm_tmul] using h\\n   410\\t  have hcom : p.asIdeal =\\n   411\\t      q.asIdeal.comap (algebraMap A (Localization.Away f)) := rfl\\n   412\\t  let rho : p.asIdeal.ResidueField →ₐ[A] q.asIdeal.ResidueField :=\\n   413\\t    Ideal.ResidueField.mapₐ p.asIdeal q.asIdeal\\n   414\\t      (Algebra.ofId A (Localization.Away f)) hcom\\n   415\\t  have hrho : Function.Bijective rho :=\\n   416\\t    (RingHom.surjectiveOnStalks_of_isLocalization (Submonoid.powers f)\\n   417\\t      (Localization.Away f)).residueFieldMap_bijective\\n   418\\t        p.asIdeal q.asIdeal hcom\\n   419\\t  let e : p.asIdeal.ResidueField ≃ₗ[A] q.asIdeal.ResidueField :=\\n   420\\t    LinearEquiv.ofBijective rho.toLinearMap hrho\\n   421\\t  have he := (e.rTensor Q).map_ne_zero_iff.mpr hp\\n   422\\t  simpa only [LinearEquiv.rTensor_tmul, e, LinearEquiv.ofBijective_apply,\\n   423\\t    AlgHom.toLinearMap_apply, map_one] using he\\n   424\\t\\n   425\\t/-- Cancelling an iterated scalar extension preserves a nonzero pure tensor. -/\\n   426\\tprivate theorem one_tmul_one_tmul_ne_zero\\n   427\\t    {R S K Q : Type u} [CommRing R] [CommRing S] [Field K]\\n   428\\t    [Algebra R S] [Algebra R K] [Algebra S K] [IsScalarTower R S K]\\n   429\\t    [AddCommGroup Q] [Module R Q]\\n   430\\t    (y : Q) (hy : ((1 : K) ⊗ₜ[R] y : K ⊗[R] Q) ≠ 0) :\\n   431\\t    ((1 : K) ⊗ₜ[S] ((1 : S) ⊗ₜ[R] y) :\\n   432\\t      K ⊗[S] (S ⊗[R] Q)) ≠ 0 := by\\n   433\\t  let e : K ⊗[S] (S ⊗[R] Q) ≃ₗ[K] K ⊗[R] Q :=\\n   434\\t    TensorProduct.AlgebraTensorModule.cancelBaseChange R S K K Q\\n   435\\t  rw [← e.map_ne_zero_iff]\\n   436\\t  simpa only [e, TensorProduct.AlgebraTensorModule.cancelBaseChange_tmul,\\n   437\\t    one_smul] using hy\\n   438\\t\\n   439\\t/-- Base change of a linear equivalence preserves nonvanishing of a pure tensor. -/\\n   440\\tprivate theorem one_tmul_linearEquiv_ne_zero\\n   441\\t    {R K M N : Type u} [CommRing R] [Field K] [Algebra R K]\\n   442\\t    [AddCommGroup M] [Module R M] [AddCommGroup N] [Module R N]\\n   443\\t    (e : M ≃ₗ[R] N) (x : M)\\n   444\\t    (hx : ((1 : K) ⊗ₜ[R] x : K ⊗[R] M) ≠ 0) :\\n   445\\t    ((1 : K) ⊗ₜ[R] e x : K ⊗[R] N) ≠ 0 := by\\n   446\\t  let eK := LinearEquiv.baseChange R K M N e\\n   447\\t  have h := eK.map_ne_zero_iff.mpr hx\\n   448\\t  simpa only [eK, LinearEquiv.baseChange_tmul] using h\\n   449\\t\\n   450\\tomit [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n   451\\t  [GeometricallyIrreducible C.hom] in\\n   452\\t/-- A nonzero cohomology class on a field fibre gives a nonzero glued section. -/\\n   453\\tprivate theorem sectionsMapTop_ne_zero_of_one_tmul_ne_zero\\n   454\\t    {B K : Type u} [CommRing B] [Algebra k B] [Field K]\\n   455\\t    [Algebra k K] [Algebra B K] [IsScalarTower k B K]\\n   456\\t    (D : BasicOpenCocycleDatum C B pi)\\n   457\\t    (hH1 : Subsingleton (datumPair D).H1)\\n   458\\t    (y : Sheaf.HModule D.sheaf 0)\\n   459\\t    (hy : ((1 : K) ⊗ₜ[B] y : K ⊗[B] Sheaf.HModule D.sheaf 0) ≠ 0) :\\n   460\\t    D.sectionsMapTop K\\n   461\\t      (Sheaf.HModule.linearEquiv₀\\n   462\\t        (Opens.grothendieckTopology ((relCurve C B : Scheme.{u}) : TopCat))\\n   463\\t        isTerminalTop D.sheaf y) ≠ 0 := by\\n   464\\t  let eDatum := D.datumH0BaseChange K hH1\\n   465\\t  have hDatum : eDatum ((1 : K) ⊗ₜ[B] y) ≠ 0 :=\\n   466\\t    eDatum.map_ne_zero_iff.mpr hy\\n   467\\t  let eSection := Sheaf.HModule.linearEquiv₀\\n   468\\t    (Opens.grothendieckTopology ((relCurve C K : Scheme.{u}) : TopCat))\\n   469\\t    isTerminalTop (D.baseChange K).sheaf\\n   470\\t  have hSection : eSection (eDatum ((1 : K) ⊗ₜ[B] y)) ≠ 0 :=\\n   471\\t    eSection.map_ne_zero_iff.mpr hDatum\\n   472\\t  rw [← D.linearEquiv₀_datumH0BaseChange_one_tmul K hH1 y]\\n   473\\t  exact hSection\\n   474\\t\\n   475\\t/-- A fibrewise-nonzero section remains nonzero after localizing and extending once more\\n   476\\tto a residue field of the localized ring. -/\\n   477\\tprivate theorem away_one_tmul_one_tmul_ne_zero\\n   478\\t    {R Q : Type u} [CommRing R] [AddCommGroup Q] [Module R Q]\\n   479\\t    (f : R) (y : Q)\\n   480\\t    (hy : ∀ p : PrimeSpectrum R, f ∉ p.asIdeal →\\n   481\\t      (y ⊗ₜ (1 : p.asIdeal.ResidueField) :\\n   482\\t        Q ⊗[R] p.asIdeal.ResidueField) ≠ 0)\\n   483\\t    (q : PrimeSpectrum (Localization.Away f)) :\\n   484\\t    ((1 : q.asIdeal.ResidueField) ⊗ₜ[Localization.Away f]\\n   485\\t      ((1 : Localization.Away f) ⊗ₜ[R] y) :\\n   486\\t      q.asIdeal.ResidueField ⊗[Localization.Away f]\\n   487\\t        (Localization.Away f ⊗[R] Q)) ≠ 0 := by\\n   488\\t  let B := Localization.Away f\\n   489\\t  let K := q.asIdeal.ResidueField\\n   490\\t  have hdirect : ((1 : K) ⊗ₜ[R] y : K ⊗[R] Q) ≠ 0 :=\\n   491\\t    fibre_tmul_ne_zero_of_away f y hy q\\n   492\\t  exact one_tmul_one_tmul_ne_zero y hdirect\\n   493\\t\\n   494\\t/-- A generator which is nonzero on every fibre of `D(f)` remains nonzero in every\\n   495\\tresidue fibre after extending the whole module to `Localization.Away f`.  This is the\\n   496\\torientation consumed by the rank-one local-basis theorem. -/\\n   497\\ttheorem tensorAwayGenerator_fibre_ne_zero\\n   498\\t    {R Q : Type u} [CommRing R] [AddCommGroup Q] [Module R Q]\\n   499\\t    (f : R) (y : Q)\\n   500\\t    (hy : ∀ p : PrimeSpectrum R, f ∉ p.asIdeal →\\n\", \"exit_code\": 0}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": \"2026-08-06T03:54:48.599493+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc \\\"nl -ba AlgebraicJacobian/Picard/Pic0RankOnePresentation.lean | sed -n '1,220p'\\\"\"}, \"usage\": null}\n{\"kind\": \"tool_result\", \"at\": \"2026-08-06T03:54:48.599508+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"     1\\t/-\\n     2\\tCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\n     3\\tReleased under Apache 2.0 license as described in the file LICENSE.\\n     4\\tAuthors: The AlgebraicJacobian Contributors\\n     5\\t-/\\n     6\\timport AlgebraicJacobian.Cohomology.ModulesBaseSheaf\\n     7\\timport AlgebraicJacobian.Cohomology.ModulesPushforwardBaseChange\\n     8\\timport AlgebraicJacobian.Cohomology.GluedSheafH0BaseChange\\n     9\\timport AlgebraicJacobian.Picard.LocalGenerators\\n    10\\timport AlgebraicJacobian.Picard.Pic0AdmissibleAbelEtaleSurjectiveH0BaseChange\\n    11\\timport AlgebraicJacobian.Picard.Pic0AdmissibleAbelEtaleSurjectiveSite\\n    12\\timport AlgebraicJacobian.Picard.Pic0EndgameContract\\n    13\\timport AlgebraicJacobian.Picard.Pic0RingDatumEngine\\n    14\\timport AlgebraicJacobian.Picard.SectionsToDivisorsClass\\n    15\\t\\n    16\\t/-!\\n    17\\t# The local-presentation contract for the rank-one Picard locus\\n    18\\t\\n    19\\tAn element of `picDegLayerFunctor` is an etale-plus class, not a chosen line bundle.  The\\n    20\\trank-one route therefore needs an explicit local presentation before it can use the evaluation\\n    21\\tmap of a line bundle.  `PicRankOneLocalPresentation` records that presentation on an affine\\n    22\\ttest and ties every piece of data to the input class:\\n    23\\t\\n    24\\t* a descent-class representative whose plus class is the affine collapse of the input;\\n    25\\t* a cocycle datum presenting that same relative Picard class;\\n    26\\t* a locally free rank-one `Scheme.Modules` object whose base-ring sheaf is the datum's sheaf;\\n    27\\t* invertibility of the canonical native pushforward base-change mate on every cartesian square;\\n    28\\t* the cohomological rank-one outputs used by the evaluation construction.\\n    29\\t\\n    30\\tNo existence, openness, or representability assertion is made here.  The first canonical\\n    31\\tconsumer is `PicRankOneLocalPresentation.evaluation`, the pullback-pushforward counit.\\n    32\\tThe method `PicRankOneLocalPresentation.h0BaseChange` derives arbitrary affine base change\\n    33\\tfrom the same presentation's `H^1`-vanishing field.  The section bridge at the end identifies\\n    34\\tdatum `H^0` with native global sections and proves, by the adjunction triangle identity, that\\n    35\\tthe evaluation counit sends the canonical unit-lift back to that same section.\\n    36\\t-/\\n    37\\t\\n    38\\tset_option autoImplicit false\\n    39\\tset_option maxSynthPendingDepth 3\\n    40\\t\\n    41\\tuniverse u\\n    42\\t\\n    43\\topen CategoryTheory Limits TopologicalSpace Opposite MonoidalCategory\\n    44\\t  CartesianMonoidalCategory\\n    45\\t\\n    46\\topen scoped TensorProduct\\n    47\\t\\n    48\\tnamespace AlgebraicGeometry\\n    49\\t\\n    50\\tattribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra\\n    51\\tattribute [local instance 10000] relCurve.instOver\\n    52\\t\\n    53\\tvariable {k : Type u} [Field k] {C : Over (Spec (.of k))}\\n    54\\tvariable [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n    55\\t  [GeometricallyIrreducible C.hom]\\n    56\\tvariable {A : Type u} [CommRing A] [Algebra k A]\\n    57\\tvariable (pi : C.left ⟶ P1 k) [IsFinite pi]\\n    58\\t\\n    59\\t/-- A rank-one presentation of a genus-degree plus class on an affine test.\\n    60\\t\\n    61\\tThe two equality fields prevent an unrelated cocycle datum or line bundle from serving as a\\n    62\\twitness: `representative` presents the input plus class, `datum_class` presents that same\\n    63\\trelative Picard class, and `module_iso` identifies the resulting cocycle sheaf with the\\n    64\\tunderlying base-ring sheaf of `module`. -/\\n    65\\tstructure PicRankOneLocalPresentation\\n    66\\t    (lam : picDegLayer C (genus C : ℤ) (overSpec k A)) : Type (u + 1) where\\n    67\\t  cover : Algebra.EtaleCover A\\n    68\\t  representative : descentClasses C cover\\n    69\\t  represents :\\n    70\\t    PicEtAff.mk C cover representative = picEtAffineEquiv C A lam.1\\n    71\\t  datum : BasicOpenCocycleDatum C cover.Carrier pi\\n    72\\t  datum_class :\\n    73\\t    (representative : relPic C (overSpec k cover.Carrier)) =\\n    74\\t      relPicMk C (overSpec k cover.Carrier) datum.cechPicClass\\n    75\\t  module : (relCurve C cover.Carrier).Modules\\n    76\\t  module_iso :\\n    77\\t    Scheme.toModuleKSheafOfModules\\n    78\\t      (Over.mk (relCurve C cover.Carrier ↘ Spec (.of cover.Carrier))) module ≅ datum.sheaf\\n    79\\t  line_bundle : Scheme.Modules.IsLineBundle module\\n    80\\t  native_pushforward_base_change :\\n    81\\t    ∀ {T' X' : Scheme.{u}}\\n    82\\t      (g : T' ⟶ Spec (.of cover.Carrier)) (f' : X' ⟶ T')\\n    83\\t      (g' : X' ⟶ relCurve C cover.Carrier)\\n    84\\t      (sq : IsPullback g' f'\\n    85\\t        (relCurve C cover.Carrier ↘ Spec (.of cover.Carrier)) g),\\n    86\\t      IsIso ((canonicalBaseChangeMap sq).app module)\\n    87\\t  h1_vanishing : Subsingleton (Sheaf.HModule datum.sheaf 1)\\n    88\\t  h0_finite : Module.Finite cover.Carrier (Sheaf.HModule datum.sheaf 0)\\n    89\\t  h0_projective : Module.Projective cover.Carrier (Sheaf.HModule datum.sheaf 0)\\n    90\\t  h0_rank_one :\\n    91\\t    ∀ p : PrimeSpectrum cover.Carrier,\\n    92\\t      Module.rankAtStalk (Sheaf.HModule datum.sheaf 0) p = 1\\n    93\\t\\n    94\\tnamespace PicRankOneLocalPresentation\\n    95\\t\\n    96\\tvariable {pi} {lam : picDegLayer C (genus C : ℤ) (overSpec k A)}\\n    97\\t\\n    98\\tnoncomputable local instance presentationModuleSections\\n    99\\t    (P : PicRankOneLocalPresentation pi lam) (U : (relCurve C P.cover.Carrier).Opens) :\\n   100\\t    Module P.cover.Carrier Γ(P.module, U) :=\\n   101\\t  Scheme.moduleKSections\\n   102\\t    (Over.mk (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))) P.module U\\n   103\\t\\n   104\\t/-- The canonical `H^0` base-change equivalence attached to a rank-one presentation.\\n   105\\t\\n   106\\tThis is derived from `P.h1_vanishing`; it is not an independently chosen witness. -/\\n   107\\tnoncomputable def h0BaseChange (P : PicRankOneLocalPresentation pi lam)\\n   108\\t    (B : Type u) [CommRing B] [Algebra k B] [Algebra P.cover.Carrier B]\\n   109\\t    [IsScalarTower k P.cover.Carrier B] :\\n   110\\t    B ⊗[P.cover.Carrier] (Sheaf.HModule P.datum.sheaf 0) ≃ₗ[B]\\n   111\\t      Sheaf.HModule (P.datum.baseChange B).sheaf 0 :=\\n   112\\t  P.datum.datumH0BaseChange B\\n   113\\t    ((subsingleton_datumPair_h1_iff P.datum).mpr P.h1_vanishing)\\n   114\\t\\n   115\\t/-- The canonical evaluation map attached to a tied local rank-one presentation. -/\\n   116\\tnoncomputable def evaluation (P : PicRankOneLocalPresentation pi lam) :\\n   117\\t    (Scheme.Modules.pullback\\n   118\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj\\n   119\\t        ((Scheme.Modules.pushforward\\n   120\\t          (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module) ⟶\\n   121\\t      P.module :=\\n   122\\t  (Scheme.Modules.pullbackPushforwardAdjunction\\n   123\\t    (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).counit.app P.module\\n   124\\t\\n   125\\t/-! ## Native pushforward base change and evaluation coherence -/\\n   126\\t\\n   127\\t/-- The canonical native pushforward base-change isomorphism supplied by the presentation.\\n   128\\t\\n   129\\tThe isomorphism is not chosen independently: its hom is definitionally\\n   130\\t`(canonicalBaseChangeMap sq).app P.module`. -/\\n   131\\tnoncomputable def nativeBaseChangeIso (P : PicRankOneLocalPresentation pi lam)\\n   132\\t    {T' X' : Scheme.{u}}\\n   133\\t    (g : T' ⟶ Spec (.of P.cover.Carrier)) (f' : X' ⟶ T')\\n   134\\t    (g' : X' ⟶ relCurve C P.cover.Carrier)\\n   135\\t    (sq : IsPullback g' f'\\n   136\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier)) g) :\\n   137\\t    (Scheme.Modules.pullback g).obj\\n   138\\t        ((Scheme.Modules.pushforward\\n   139\\t          (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module) ≅\\n   140\\t      (Scheme.Modules.pushforward f').obj ((Scheme.Modules.pullback g').obj P.module) := by\\n   141\\t  exact @asIso _ _ _ _ ((canonicalBaseChangeMap sq).app P.module)\\n   142\\t    (P.native_pushforward_base_change g f' g' sq)\\n   143\\t\\n   144\\t/-- The native pushforward base-change isomorphism for an affine coefficient extension. -/\\n   145\\tnoncomputable def nativeBaseChangeIsoAffine (P : PicRankOneLocalPresentation pi lam)\\n   146\\t    (B : Type u) [CommRing B] [Algebra k B] [Algebra P.cover.Carrier B]\\n   147\\t    [IsScalarTower k P.cover.Carrier B] :\\n   148\\t    (Scheme.Modules.pullback\\n   149\\t      (Spec.map (CommRingCat.ofHom (algebraMap P.cover.Carrier B)))).obj\\n   150\\t        ((Scheme.Modules.pushforward\\n   151\\t          (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module) ≅\\n   152\\t      (Scheme.Modules.pushforward\\n   153\\t        (relCurve C B ↘ Spec (.of B))).obj\\n   154\\t          ((Scheme.Modules.pullback (relCurveMap C P.cover.Carrier B)).obj P.module) :=\\n   155\\t  P.nativeBaseChangeIso\\n   156\\t    (overSpecMap (k := k) P.cover.Carrier B).left\\n   157\\t    (snd C (overSpec k B)).left\\n   158\\t    (relCurveMap C P.cover.Carrier B)\\n   159\\t    (Over.isPullback_whiskerLeft C (overSpecMap (k := k) P.cover.Carrier B))\\n   160\\t\\n   161\\t/-- The source of evaluation identifies canonically with the source of evaluation after any\\n   162\\tcartesian base change. -/\\n   163\\tnoncomputable def evaluationSourceBaseChangeIso (P : PicRankOneLocalPresentation pi lam)\\n   164\\t    {T' X' : Scheme.{u}}\\n   165\\t    (g : T' ⟶ Spec (.of P.cover.Carrier)) (f' : X' ⟶ T')\\n   166\\t    (g' : X' ⟶ relCurve C P.cover.Carrier)\\n   167\\t    (sq : IsPullback g' f'\\n   168\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier)) g) :\\n   169\\t    (Scheme.Modules.pullback\\n   170\\t        (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier)) ⋙\\n   171\\t      Scheme.Modules.pullback g').obj\\n   172\\t        ((Scheme.Modules.pushforward\\n   173\\t          (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module) ≅\\n   174\\t      (Scheme.Modules.pushforward f' ⋙ Scheme.Modules.pullback f').obj\\n   175\\t        ((Scheme.Modules.pullback g').obj P.module) :=\\n   176\\t  ((((Scheme.Modules.pullbackComp f' g) ≪≫\\n   177\\t    Scheme.Modules.pullbackCongr sq.w.symm ≪≫\\n   178\\t    (Scheme.Modules.pullbackComp g'\\n   179\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).symm).app\\n   180\\t        ((Scheme.Modules.pushforward\\n   181\\t          (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carrier))).obj P.module)).symm) ≪≫\\n   182\\t    (Scheme.Modules.pullback f').mapIso (P.nativeBaseChangeIso g f' g' sq)\\n   183\\t\\n   184\\t/-- Under the source identification, evaluation after base change is the pullback of the\\n   185\\tpresentation's original evaluation counit. -/\\n   186\\ttheorem evaluationSourceBaseChangeIso_hom_evaluation\\n   187\\t    (P : PicRankOneLocalPresentation pi lam)\\n   188\\t    {T' X' : Scheme.{u}}\\n   189\\t    (g : T' ⟶ Spec (.of P.cover.Carrier)) (f' : X' ⟶ T')\\n   190\\t    (g' : X' ⟶ relCurve C P.cover.Carrier)\\n   191\\t    (sq : IsPullback g' f'\\n   192\\t      (relCurve C P.cover.Carrier ↘ Spec (.of P.cover.Carr