     = Scheme.CechPic.map (relCurveMap C S p.asIdeal.ResidueField) F₀.picClass\\n   120\\t      ∧ Subsingleton (Sheaf.HModule\\n   121\\t          ((C ⊗ overSpec k p.asIdeal.ResidueField).left.divisorSheaf\\n   122\\t            p.asIdeal.ResidueField W) 1)\\n   123\\t\\n   124\\t/-! ## (V1a) Witness production and class-only dependence -/\\n   125\\t\\n   126\\tomit [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n   127\\t  [GeometricallyIrreducible C.hom] in\\n   128\\t/-- **The class law of the field dictionary's forward map**: the Čech Picard class of\\n   129\\tthe Weil divisor of a divisor family over a field is the class of the family. -/\\n   130\\ttheorem picClass_divFamDivisor {L : Type u} [Field L] [Algebra k L]\\n   131\\t    [IsIntegral (relCurve C L)]\\n   132\\t    [SmoothOfRelativeDimension 1 (relCurve C L ↘ Spec (CommRingCat.of L))]\\n   133\\t    [QuasiCompact (relCurve C L ↘ Spec (CommRingCat.of L))]\\n   134\\t    (G : DivFam C L π n) :\\n   135\\t    Scheme.CurveDivisor.picClass L (divFamDivisor G) = G.picClass := by\\n   136\\t  induction G using Quotient.inductionOn with\\n   137\\t  | h F =>\\n   138\\t    rw [show (⟦F⟧ : DivFam C L π n) = DivFam.mk F from rfl, divFamDivisor_mk,\\n   139\\t      Scheme.CurveDivisor.picClass_presentationDivisor,\\n   140\\t      Scheme.LocalEquations.presentation_picClass, DivFam.picClass_mk]\\n   141\\t\\n   142\\t/-- **(V1a) witness production**: at every field `L` of the test tower, the fibre\\n   143\\tclass of a locally certified degree-`n` class has an **effective** witness divisor of\\n   144\\tdegree `n` — `divFamDivisor` of a globally certified representative of the restricted\\n   145\\tclass (`DivFam.exists_toZar_eq`). -/\\n   146\\ttheorem DivFamZar.exists_effective_witness (F₀ : DivFamZar C S π n) (L : Type u)\\n   147\\t    [Field L] [Algebra k L] [Algebra S L] [IsScalarTower k S L] :\\n   148\\t    ∃ W : ((C ⊗ overSpec k L).left).CurveDivisor,\\n   149\\t      0 ≤ W\\n   150\\t        ∧ Scheme.CurveDivisor.picClass L W\\n   151\\t            = Scheme.CechPic.map (relCurveMap C S L) F₀.picClass\\n   152\\t        ∧ Scheme.CurveDivisor.deg L W = (n : ℤ) := by\\n   153\\t  haveI : IsIntegral (relCurve C L) := instIsIntegralBaseChange C L\\n   154\\t  haveI : SmoothOfRelativeDimension 1 (relCurve C L ↘ Spec (CommRingCat.of L)) :=\\n   155\\t    instSmoothOfRelativeDimensionBaseChange C L\\n   156\\t  haveI : QuasiCompact (relCurve C L ↘ Spec (CommRingCat.of L)) :=\\n   157\\t    instQuasiCompactBaseChange C L\\n   158\\t  obtain ⟨G, hG⟩ := DivFam.exists_toZar_eq (DivFamZar.mapAlg L n F₀)\\n   159\\t  refine ⟨divFamDivisor G, zero_le_divFamDivisor G, ?_, deg_divFamDivisor G⟩\\n   160\\t  rw [picClass_divFamDivisor G, ← DivFamZar.picClass_toZar, hG,\\n   161\\t    DivFamZar.picClass_mapAlg]\\n   162\\t\\n   163\\t/-- **(V1a) class-only dependence — any witness serves**: if `F₀` is h¹-vanishing at\\n   164\\t`p`, then `H¹(𝒪(W))` vanishes for EVERY witness divisor `W` of the fibre class\\n   165\\t(`subsingleton_hModule_one_of_picClass_eq`). -/\\n   166\\ttheorem DivFamZar.IsH1VanishingAt.subsingleton_of_picClass_eq\\n   167\\t    {F₀ : DivFamZar C S π n} {p : PrimeSpectrum S} (hvan : F₀.IsH1VanishingAt p)\\n   168\\t    {W : ((C ⊗ overSpec k p.asIdeal.ResidueField).left).CurveDivisor}\\n   169\\t    (hW : Scheme.CurveDivisor.picClass p.asIdeal.ResidueField W\\n   170\\t      = Scheme.CechPic.map (relCurveMap C S p.asIdeal.ResidueField) F₀.picClass) :\\n   171\\t    Subsingleton (Sheaf.HModule\\n   172\\t      ((C ⊗ overSpec k p.asIdeal.ResidueField).left.divisorSheaf\\n   173\\t        p.asIdeal.ResidueField W) 1) := by\\n   174\\t  obtain ⟨W₀, hW₀, hsub⟩ := hvan\\n   175\\t  exact subsingleton_hModule_one_of_picClass_eq p.asIdeal.ResidueField\\n   176\\t    (hW₀.trans hW.symm) hsub\\n   177\\t\\n   178\\t/-- **(V1a), iff form**: against any fixed witness of the fibre class, membership is\\n   179\\texactly the vanishing of `H¹(𝒪(W))`. -/\\n   180\\ttheorem DivFamZar.isH1VanishingAt_iff_of_picClass_eq\\n   181\\t    {F₀ : DivFamZar C S π n} {p : PrimeSpectrum S}\\n   182\\t    {W : ((C ⊗ overSpec k p.asIdeal.ResidueField).left).CurveDivisor}\\n   183\\t    (hW : Scheme.CurveDivisor.picClass p.asIdeal.ResidueField W\\n   184\\t      = Scheme.CechPic.map (relCurveMap C S p.asIdeal.ResidueField) F₀.picClass) :\\n   185\\t    F₀.IsH1VanishingAt p ↔ Subsingleton (Sheaf.HModule\\n   186\\t      ((C ⊗ overSpec k p.asIdeal.ResidueField).left.divisorSheaf\\n   187\\t        p.asIdeal.ResidueField W) 1) :=\\n   188\\t  ⟨fun hvan => hvan.subsingleton_of_picClass_eq hW, fun hsub => ⟨W, hW, hsub⟩⟩\\n   189\\t\\n   190\\t/-! ## The two-way datum dictionary (the heart of GAP-6) -/\\n   191\\t\\n   192\\t/-- **The two-way fibre dictionary of the datum engine** (worksheet (V1b), stated at an\\n   193\\tarbitrary field of the test tower): for a pinned cocycle datum `D` over `S` and a field\\n   194\\t`L` in a `k`/`S`-tower, the engine's complex-form fibre condition\\n   195\\t`Subsingleton (H¹(pair D) ⊗[S] L)` holds iff the mapped class of the datum has a\\n   196\\tvanishing-`H¹` witness divisor over `L`.\\n   197\\t\\n   198\\tForward: right-exactness (`subsingleton_h1_rTensor_iff`) makes the base-changed Čech\\n   199\\tdifferential surjective; the δ-naturality square (`datumDiffBaseChange`) carries\\n   200\\tsurjectivity to the fibre datum's differential; `subsingleton_datumPair_h1_iff`, the\\n   201\\tpresentation bridge (`presentationSheafIso`) and the core isomorphism\\n   202\\t(`subsingleton_hModule_gluedSheaf_one_iff`) then read the vanishing on the witness\\n   203\\t`presentationDivisor` of the canonical subordinated presentation.  Backward: the landed\\n   204\\tseam `subsingleton_sheaf_h1_of_picClass_eq` + `subsingleton_h1_tensor_of_baseChange_sheaf`. -/\\n   205\\ttheorem BasicOpenCocycleDatum.subsingleton_h1_tensor_iff_exists_witness\\n   206\\t    (D : BasicOpenCocycleDatum C S π) (L : Type u) [Field L] [Algebra k L]\\n   207\\t    [Algebra S L] [IsScalarTower k S L] :\\n   208\\t    Subsingleton ((datumPair D).H1 ⊗[S] L) ↔\\n   209\\t      ∃ W : ((C ⊗ overSpec k L).left).CurveDivisor,\\n   210\\t        Scheme.CurveDivisor.picClass L W\\n   211\\t            = Scheme.CechPic.map (relCurveMap C S L) D.cechPicClass\\n   212\\t          ∧ Subsingleton (Sheaf.HModule\\n   213\\t              ((C ⊗ overSpec k L).left.divisorSheaf L W) 1) := by\\n   214\\t  haveI : IsIntegral (relCurve C L) := instIsIntegralBaseChange C L\\n   215\\t  haveI : SmoothOfRelativeDimension 1 (relCurve C L ↘ Spec (CommRingCat.of L)) :=\\n   216\\t    instSmoothOfRelativeDimensionBaseChange C L\\n   217\\t  haveI : QuasiCompact (relCurve C L ↘ Spec (CommRingCat.of L)) :=\\n   218\\t    instQuasiCompactBaseChange C L\\n   219\\t  constructor\\n   220\\t  · intro h\\n   221\\t    -- surjectivity of the base-changed differential, through right-exactness\\n   222\\t    have hcok := ((datumPair D).subsingleton_h1_rTensor_iff L).mp h\\n   223\\t    have hbc : Function.Surjective ((datumPair D).diff.baseChange L) := by\\n   224\\t      rw [← LinearMap.range_eq_top]\\n   225\\t      exact Submodule.Quotient.subsingleton_iff.mp hcok\\n   226\\t    -- across the δ-naturality square to the fibre datum's differential\\n   227\\t    have hsurj' : Function.Surjective (datumPair (D.baseChange L)).diff :=\\n   228\\t      RigidEngine.surjective_congr _ _ (D.datumDomBaseChange L)\\n   229\\t        (D.termBaseChangeInf L) (fun x => D.datumDiffBaseChange L x) hbc\\n   230\\t    haveI hH1L : Subsingleton (datumPair (D.baseChange L)).H1 := by\\n   300\\t`Ideal.ResidueField.map` is bijective (localizations are surjective on stalks) and\\n   301\\t`R'`-linear (`IsLocalization.ringHom_ext`). -/\\n   302\\tprivate theorem subsingleton_tensor_residueField_comap_iff\\n   303\\t    {S₀ R' : Type u} [CommRing S₀] [CommRing R'] [Algebra S₀ R'] (M₀ : Submonoid S₀)\\n   304\\t    [IsLocalization M₀ R'] (M : Type u) [AddCommGroup M] [Module R' M]\\n   305\\t    (q : PrimeSpectrum R')\\n   306\\t    [Algebra R' (PrimeSpectrum.comap (algebraMap S₀ R') q).asIdeal.ResidueField]\\n   307\\t    [IsScalarTower S₀ R'\\n   308\\t      (PrimeSpectrum.comap (algebraMap S₀ R') q).asIdeal.ResidueField] :\\n   309\\t    Subsingleton (M ⊗[R']\\n   310\\t        (PrimeSpectrum.comap (algebraMap S₀ R') q).asIdeal.ResidueField) ↔\\n   311\\t      Subsingleton (M ⊗[R'] q.asIdeal.ResidueField) := by\\n   312\\t  have hcom : (PrimeSpectrum.comap (algebraMap S₀ R') q).asIdeal\\n   313\\t      = q.asIdeal.comap (algebraMap S₀ R') := rfl\\n   314\\t  refine subsingleton_tensor_congr_of_bijective\\n   315\\t    (Ideal.ResidueField.map _ q.asIdeal (algebraMap S₀ R') hcom) ?_ ?_\\n   316\\t  · refine IsLocalization.ringHom_ext M₀ (RingHom.ext fun s => ?_)\\n   317\\t    rw [RingHom.comp_apply, RingHom.comp_apply, RingHom.comp_apply,\\n   318\\t      ← IsScalarTower.algebraMap_apply S₀ R', Ideal.ResidueField.map_algebraMap]\\n   319\\t  · exact (RingHom.surjectiveOnStalks_of_isLocalization (M := M₀)\\n   320\\t      R').residueFieldMap_bijective _ q.asIdeal hcom\\n   321\\t\\n   322\\t/-- **(V1c) the away-piece bridge** (worksheet §1.2 locality, the openness engine's\\n   323\\tconsumption shape): if the away piece `Localization.Away f` carries a certified\\n   324\\trepresentative `G` of the restricted class, then membership of `F₀` at the trace\\n   325\\t`comap q` of a prime `q` of the piece is exactly the engine's fibre condition of the\\n   326\\tpiece's divisor datum at `q`.  In particular the predicate is invariant under\\n   327\\t`mapAlg` along `S → Localization.Away f` at lying-over primes. -/\\n   328\\ttheorem DivFamZar.isH1VanishingAt_comap_away_iff (F₀ : DivFamZar C S π n) (f : S)\\n   329\\t    (G : CertifiedDivisorFamily C (Localization.Away f) π n)\\n   330\\t    (hGZ : (DivFam.mk G).toZar = DivFamZar.mapAlg (Localization.Away f) n F₀)\\n   331\\t    (q : PrimeSpectrum (Localization.Away f)) :\\n   332\\t    F₀.IsH1VanishingAt (PrimeSpectrum.comap (algebraMap S (Localization.Away f)) q)\\n   333\\t      ↔ Subsingleton ((datumPair G.adaptation.divisorDatum).H1\\n   334\\t          ⊗[Localization.Away f] q.asIdeal.ResidueField) := by\\n   335\\t  -- `f` is invertible at the trace prime, so `κ(comap q)` receives the localization\\n   336\\t  have hfp : f ∉ (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   337\\t      q).asIdeal := by\\n   338\\t    intro hf\\n   339\\t    refine q.isPrime.ne_top (Ideal.eq_top_of_isUnit_mem q.asIdeal\\n   340\\t      (Ideal.mem_comap.mp hf) ?_)\\n   341\\t    exact IsLocalization.Away.algebraMap_isUnit f\\n   342\\t  have hunit : IsUnit (algebraMap S\\n   343\\t      (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   344\\t        q).asIdeal.ResidueField f) :=\\n   345\\t    isUnit_iff_ne_zero.mpr fun h0 => hfp (Ideal.algebraMap_residueField_eq_zero.mp h0)\\n   346\\t  letI : Algebra (Localization.Away f)\\n   347\\t      (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   348\\t        q).asIdeal.ResidueField :=\\n   349\\t    (IsLocalization.Away.lift (S := Localization.Away f) f hunit).toAlgebra\\n   350\\t  haveI : IsScalarTower S (Localization.Away f)\\n   351\\t      (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   352\\t        q).asIdeal.ResidueField :=\\n   353\\t    IsScalarTower.of_algebraMap_eq' (by\\n   354\\t      rw [RingHom.algebraMap_toAlgebra, IsLocalization.Away.lift_comp])\\n   355\\t  haveI : IsScalarTower k (Localization.Away f)\\n   356\\t      (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   357\\t        q).asIdeal.ResidueField :=\\n   358\\t    isScalarTower_left_of_isScalarTower (R₀ := S)\\n   359\\t  -- the class of the piece datum, pulled to `κ(comap q)`, is the mapped class of `F₀`\\n   360\\t  have hZcl : G.eqns.picClass\\n   361\\t      = Scheme.CechPic.map (relCurveMap C S (Localization.Away f)) F₀.picClass := by\\n   362\\t    have h := congrArg DivFamZar.picClass hGZ\\n   363\\t    rw [DivFamZar.picClass_toZar, DivFam.picClass_mk, DivFamZar.picClass_mapAlg] at h\\n   364\\t    exact h\\n   365\\t  have hdict := (G.adaptation.divisorDatum.subsingleton_h1_tensor_iff_exists_witness\\n   366\\t    (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   367\\t      q).asIdeal.ResidueField).symm\\n   368\\t  rw [G.adaptation.cechPicClass_divisorDatum, hZcl, ← MonoidHom.comp_apply,\\n   369\\t    ← Scheme.CechPic.map_comp,\\n   370\\t    relCurveMap_comp (R' := Localization.Away f)\\n   371\\t      (R'' := (PrimeSpectrum.comap (algebraMap S (Localization.Away f))\\n   372\\t        q).asIdeal.ResidueField)]\\n   373\\t    at hdict\\n   374\\t  exact hdict.trans\\n   375\\t    (subsingleton_tensor_residueField_comap_iff (Submonoid.powers f) _ q)\\n   376\\t\\n   377\\t/-! ## §1.3 Openness on affine tests (the ONE audited mechanism) -/\\n   378\\t\\n   379\\t/-- **Openness of the h¹-vanishing locus on an affine test** (worksheet §1.3): the\\n   380\\tlocus `{p | IsH1VanishingAt F₀ p}` is open in `Spec S`.  Per certificate piece of\\n   381\\t`DivFamZar.exists_certified_away_rep` the trace of the locus is the engine open\\n   382\\t`datumRigidEngine_isOpen_vanishing` of the piece's divisor datum ((V1b) + (V1c)),\\n   383\\tcarried across the away open immersion; the pieces glue since they compute one\\n   384\\tpredicate.  This is the single sanctioned openness mechanism of the campaign\\n   385\\t(dat-d §3.5): no Fitting ideals, no semicontinuity, Noetherian-free. -/\\n   386\\ttheorem DivFamZar.isOpen_setOf_isH1VanishingAt\\n   387\\t    (hπ : π ≫ P1.structureMap k = C.hom) (F₀ : DivFamZar C S π n) :\\n   388\\t    IsOpen {p : PrimeSpectrum S | F₀.IsH1VanishingAt p} := by\\n   389\\t  obtain ⟨m, h, hspan, hG⟩ := DivFamZar.exists_certified_away_rep F₀\\n   390\\t  choose G hGZ using hG\\n   391\\t  have hkey : {p : PrimeSpectrum S | F₀.IsH1VanishingAt p}\\n   392\\t      = ⋃ l : Fin m,\\n   393\\t          (PrimeSpectrum.comap (algebraMap S (Localization.Away (h l)))) ''\\n   394\\t            {q : PrimeSpectrum (Localization.Away (h l)) |\\n   395\\t              Subsingleton ((datumPair (G l).adaptation.divisorDatum).H1\\n   396\\t                ⊗[Localization.Away (h l)] q.asIdeal.ResidueField)} := by\\n   397\\t    ext p\\n   398\\t    simp only [Set.mem_setOf_eq, Set.mem_iUnion, Set.mem_image]\\n   399\\t    constructor\\n   400\\t    · intro hp\\n   401\\t      -- some certificate piece sees `p` (span-⊤ prime avoidance)\\n   402\\t      have hex : ∃ l, h l ∉ p.asIdeal := by\\n   403\\t        by_contra hall\\n   404\\t        have hmem : ∀ l, h l ∈ p.asIdeal := fun l => of_not_not fun hl => hall ⟨l, hl⟩\\n   405\\t        have hle : Ideal.span (Set.range h) ≤ p.asIdeal :=\\n   406\\t          Ideal.span_le.mpr (by rintro x ⟨l, rfl⟩; exact hmem l)\\n   407\\t        rw [hspan] at hle\\n   408\\t        exact p.isPrime.ne_top (top_le_iff.mp hle)\\n   409\\t      obtain ⟨l, hl⟩ := hex\\n   410\\t      have hrange : p ∈ Set.range\\n   411\\t          (PrimeSpectrum.comap (algebraMap S (Localization.Away (h l)))) := by\\n   412\\t        rw [PrimeSpectrum.localization_away_comap_range\\n   413\\t          (S := Localization.Away (h l)) (h l)]\\n   414\\t        exact hl\\n   415\\t      obtain ⟨q, hq⟩ := hrange\\n   416\\t      exact ⟨l, q,\\n   417\\t        (F₀.isH1VanishingAt_comap_away_iff (h l) (G l) (hGZ l) q).mp (hq ▸ hp), hq⟩\\n   418\\t    · rintro ⟨l, q, hsub, rfl⟩\\n   419\\t      exact (F₀.isH1VanishingAt_comap_away_iff (h l) (G l) (hGZ l) q).mpr hsub\\n   420\\t  rw [hkey]\\n   421\\t  refine isOpen_iUnion fun l => ?_\\n   422\\t  refine (PrimeSpectrum.localization_away_isOpenEmbedding\\n   423\\t    (Localization.Away (h l)) (h l)).isOpenMap _ ?_\\n   424\\t  exact datumRigidEngine_isOpen_vanishing (G l).adaptation.divisorDatum hπ\\n   425\\t\\n   426\\tend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n{\"kind\": \"tool_call\", \"at\": 