ion-restriction algebra map.\\n    83\\t\\n    84\\tIdentical in shape to `divFamZar` (`DivisorFamilyZarVehicle.lean`), with `DivFamZarAff` in\\n    85\\tplace of `DivFamZar` — R2 widens the curve side and leaves the base side alone.  The\\n    86\\tcompatibility is spelled with `DivFamZarAff.mapAlgHom`, which is why the explicit-map face had\\n    87\\tto be built first: `Over.resAlgHom` carries no algebra-tower instance. -/\\n    88\\tdef divFamZarAff (T : Over (Spec (.of k))) : Type u :=\\n    89\\t  {s : Π U : T.left.affineOpens, DivFamZarAff C Γ(T.left, U.1) n //\\n    90\\t    ∀ (U V : T.left.affineOpens) (h : U.1 ≤ V.1),\\n    91\\t      DivFamZarAff.mapAlgHom (Over.resAlgHom T h) (s V) = s U}\\n    92\\t\\n    93\\tnamespace divFamZarAff\\n    94\\t\\n    95\\tvariable {C n} {T : Over (Spec (.of k))}\\n    96\\t\\n    97\\t/-- The compatibility of a section of `divFamZarAff` along an inclusion of affine opens. -/\\n    98\\tlemma compat (s : divFamZarAff C n T) (U V : T.left.affineOpens) (h : U.1 ≤ V.1) :\\n    99\\t    DivFamZarAff.mapAlgHom (Over.resAlgHom T h) (s.1 V) = s.1 U :=\\n   100\\t  s.2 U V h\\n   101\\t\\n   102\\t/-- Two sections of `divFamZarAff` agreeing at every affine open are equal. -/\\n   103\\t@[ext]\\n   104\\tlemma ext {s t : divFamZarAff C n T} (h : ∀ U : T.left.affineOpens, s.1 U = t.1 U) :\\n   105\\t    s = t :=\\n   106\\t  Subtype.ext (funext h)\\n   107\\t\\n   108\\tvariable (C n T) in\\n   109\\t/-- Evaluation of a section of `divFamZarAff` at an affine open. -/\\n   110\\tdef eval (U : T.left.affineOpens) : divFamZarAff C n T → DivFamZarAff C Γ(T.left, U.1) n :=\\n   111\\t  fun s => s.1 U\\n   112\\t\\n   113\\t/-- Evaluation is projection to the component at the affine open. -/\\n   114\\t@[simp]\\n   115\\tlemma eval_apply (U : T.left.affineOpens) (s : divFamZarAff C n T) :\\n   116\\t    eval C n T U s = s.1 U :=\\n   117\\t  rfl\\n   118\\t\\n   119\\tend divFamZarAff\\n   120\\t\\n   121\\t/-! ## The affine comparison -/\\n   122\\t\\n   123\\tsection Affine\\n   124\\t\\n   125\\tvariable (R : Type u) [CommRing R] [Algebra k R]\\n   126\\t\\n   127\\t/-- Evaluation at the top affine open of an affine test, composed with the `ΓSpecIso`-transport\\n   128\\tinto the test algebra: the forward direction of the widened affine comparison. -/\\n   129\\tdef divFamZarAffToAff : divFamZarAff C n (overSpec k R) → DivFamZarAff C R n :=\\n   130\\t  fun s => DivFamZarAff.congr (Over.overSpecΓTopAlgEquiv k R) (s.1 (overSpecTopAffine R))\\n   131\\t\\n   132\\t/-- The section of `divFamZarAff` over an affine test determined by a widened locally certified\\n   133\\tclass of the test algebra: restrict from the top affine open. -/\\n   134\\tdef divFamZarAffOfAff : DivFamZarAff C R n → divFamZarAff C n (overSpec k R) :=\\n   135\\t  fun x =>\\n   136\\t    ⟨fun U => DivFamZarAff.mapAlgHom\\n   137\\t      ((Over.resAlgHom (overSpec k R) le_top).comp\\n   138\\t        (Over.overSpecΓTopAlgEquiv k R).symm.toAlgHom) x,\\n   139\\t      fun U V h => by rw [← DivFamZarAff.mapAlgHom_comp, ← AlgHom.comp_assoc,\\n   140\\t        Over.resAlgHom_comp]⟩\\n   141\\t\\n   142\\t/-- The value of `divFamZarAffOfAff` at every affine open is the restricted transported\\n   143\\tclass. -/\\n   144\\tlemma divFamZarAffOfAff_val (x : DivFamZarAff C R n)\\n   145\\t    (U : (overSpec k R).left.affineOpens) :\\n   146\\t    (divFamZarAffOfAff C n R x).1 U\\n   147\\t      = DivFamZarAff.mapAlgHom\\n   148\\t          ((Over.resAlgHom (overSpec k R) le_top).comp\\n   149\\t            (Over.overSpecΓTopAlgEquiv k R).symm.toAlgHom) x :=\\n   150\\t  rfl\\n   151\\t\\n   152\\t/-- Round trip on the vehicle side: restricting the transported top value recovers every\\n   153\\tcomponent, by the compatibility of the section. -/\\n   154\\tprivate lemma divFamZarAffOfAff_divFamZarAffToAff (s : divFamZarAff C n (overSpec k R)) :\\n   155\\t    divFamZarAffOfAff C n R (divFamZarAffToAff C n R s) = s := by\\n   156\\t  ref